/* Generated from Moru UI source. Do not edit. SPDX-License-Identifier: MIT */
:where([data-moru-registry]) .ui-footer {
  --page-chrome-control-height: var(--ui-control-height-md, 40px);
  box-sizing: border-box;
  width: 100%;
  min-width: 0;
  padding: var(--ui-card-padding, 24px);
  border: var(--ui-border-width, 0px) solid var(--ui-border);
  border-radius: var(--ui-card-radius);
  background: var(--ui-surface);
  color: var(--ui-text);
  font-family: var(--ui-font-family);
}

:where([data-moru-registry]) .ui-footer[data-size='sm'] {
  --page-chrome-control-height: var(--ui-control-height-sm, 32px);
}

:where([data-moru-registry]) .ui-footer[data-size='lg'] {
  --page-chrome-control-height: var(--ui-control-height-lg, 48px);
}

:where([data-moru-registry]) .ui-footer .ui-footer-navigation a,
:where([data-moru-registry]) .ui-footer .ui-footer-navigation button,
:where([data-moru-registry]) .ui-footer .ui-footer-column a,
:where([data-moru-registry]) .ui-footer .ui-footer-column button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: var(--page-chrome-control-height);
  max-width: 100%;
  padding: calc(var(--ui-space, 4px) * 1.5) calc(var(--ui-space, 4px) * 2);
  border: 0;
  border-radius: var(--ui-radius);
  background: transparent;
  color: var(--ui-muted);
  font: inherit;
  font-size: var(--ui-type-caption-size, 12px);
  line-height: var(--ui-type-caption-line-height, 1.5);
  text-align: start;
  text-decoration: none;
  overflow-wrap: anywhere;
  cursor: pointer;
}

:where([data-moru-registry]) .ui-footer .ui-footer-navigation a:hover,
:where([data-moru-registry]) .ui-footer .ui-footer-navigation button:hover,
:where([data-moru-registry]) .ui-footer .ui-footer-column a:hover,
:where([data-moru-registry]) .ui-footer .ui-footer-column button:hover {
  background: var(--ui-control-hover-bg);
  color: var(--ui-text);
}

:where([data-moru-registry]) .ui-footer .ui-footer-navigation button:disabled,
:where([data-moru-registry]) .ui-footer .ui-footer-column button:disabled {
  opacity: var(--ui-disabled-opacity, 0.45);
  cursor: not-allowed;
}

:where([data-moru-registry]) .ui-footer a:focus-visible,
:where([data-moru-registry]) .ui-footer button:focus-visible {
  outline: 2px solid var(--ui-focus-ring, var(--ui-primary));
  outline-offset: 3px;
}

:where([data-moru-registry]) .ui-footer {
  container: moru-footer / inline-size;
}

:where([data-moru-registry]) .ui-footer-main,
:where([data-moru-registry]) .ui-footer-bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: calc(var(--ui-space, 4px) * 4);
  min-width: 0;
}

:where([data-moru-registry]) .ui-footer-identity {
  flex: 1;
  min-width: min(160px, 100%);
}

:where([data-moru-registry]) .ui-footer-brand {
  font-size: var(--ui-type-label-size, 14px);
  font-weight: var(--ui-type-heading-weight, 600);
  line-height: var(--ui-type-label-line-height, 1.5);
}

:where([data-moru-registry]) .ui-footer-description {
  max-width: 34ch;
  margin-top: var(--ui-field-gap, 8px);
  color: var(--ui-muted);
  font-size: var(--ui-type-caption-size, 12px);
  line-height: var(--ui-type-body-line-height, 1.6);
  word-break: keep-all;
  overflow-wrap: anywhere;
}

:where([data-moru-registry]) .ui-footer-navigation {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: var(--ui-control-gap, 8px);
  min-width: 0;
}

:where([data-moru-registry]) .ui-footer-columns {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(120px, 100%), 1fr));
  flex: 2;
  min-width: min(280px, 100%);
  gap: var(--ui-card-padding, 24px);
}

:where([data-moru-registry]) .ui-footer-column {
  min-width: 0;
}

:where([data-moru-registry]) .ui-footer-column h3 {
  margin: 0 0 var(--ui-field-gap, 8px);
  font-size: var(--ui-type-label-size, 14px);
  font-weight: var(--ui-type-label-weight, 500);
  line-height: var(--ui-type-label-line-height, 1.5);
}

:where([data-moru-registry]) .ui-footer-column ul,
:where([data-moru-registry]) .ui-footer-column ol {
  display: grid;
  gap: var(--ui-space, 4px);
  padding: 0;
  margin: 0;
  list-style: none;
}

:where([data-moru-registry]) .ui-footer .ui-footer-column a,
:where([data-moru-registry]) .ui-footer .ui-footer-column button {
  justify-content: flex-start;
  padding-inline: 0;
}

:where([data-moru-registry]) .ui-footer-bottom,
:where([data-moru-registry]) .ui-footer-content {
  margin-top: var(--ui-form-gap, 24px);
}

:where([data-moru-registry]) .ui-footer-bottom:first-child,
:where([data-moru-registry]) .ui-footer-content:first-child {
  margin-top: 0;
}

:where([data-moru-registry]) .ui-footer-copyright,
:where([data-moru-registry]) .ui-footer-meta {
  color: var(--ui-muted);
  font-size: var(--ui-type-caption-size, 12px);
  line-height: var(--ui-type-caption-line-height, 1.5);
  overflow-wrap: anywhere;
}

:where([data-moru-registry]) .ui-footer-meta {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: var(--ui-control-gap, 8px);
}

:where([data-moru-registry]) .ui-footer[data-variant='columns'] .ui-footer-main {
  align-items: flex-start;
  gap: var(--ui-form-gap, 24px);
}

:where([data-moru-registry]) .ui-footer[data-variant='compact'] {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: calc(var(--ui-space, 4px) * 4);
  padding-block: calc(var(--ui-card-padding, 24px) * 0.5);
}

:where([data-moru-registry]) .ui-footer[data-variant='compact'] .ui-footer-bottom {
  margin-top: 0;
}

@container moru-footer (max-width: 440px) {
  :where([data-moru-registry]) .ui-footer-main,
  :where([data-moru-registry]) .ui-footer-bottom {
    align-items: flex-start;
    flex-direction: column;
  }

  :where([data-moru-registry]) .ui-footer-columns {
    width: 100%;
  }
}

@media (pointer: coarse) {
  :where([data-moru-registry]) .ui-footer .ui-footer-navigation a,
  :where([data-moru-registry]) .ui-footer .ui-footer-navigation button,
  :where([data-moru-registry]) .ui-footer .ui-footer-column a,
  :where([data-moru-registry]) .ui-footer .ui-footer-column button {
    min-height: 44px;
  }
}

'use client'
// Generated from Moru UI source. Do not edit. SPDX-License-Identifier: MIT
import { useI18n } from './_lib/i18n'
import { forwardRef, type HTMLAttributes, type ReactNode } from 'react'
import { cn } from './_lib/cn'
import './footer.css'

export interface FooterColumn {
  title: string
  content: ReactNode
  /** Distinguish repeated group titles when more than one footer is present. */
  label?: string
}

export type FooterProps = HTMLAttributes<HTMLElement> & {
  brand?: ReactNode
  description?: ReactNode
  navigation?: ReactNode
  navigationLabel?: string
  columns?: readonly FooterColumn[]
  copyright?: ReactNode
  meta?: ReactNode
  variant?: 'simple' | 'columns' | 'compact'
  size?: 'sm' | 'md' | 'lg'
}

/** Compose product links, legal information, and status without imposing a router. */
export const Footer = forwardRef<HTMLElement, FooterProps>(function Footer(
  {
    brand,
    description,
    navigation,
    navigationLabel: navigationLabelProp,
    columns,
    copyright,
    meta,
    variant = 'simple',
    size = 'md',
    children,
    className,
    ...props
  },
  ref,
) {
  const { t } = useI18n()
  const navigationLabel = navigationLabelProp ?? t('푸터 탐색')

  return (
    <footer
      {...props}
      ref={ref}
      className={cn('ui-footer', className)}
      data-variant={variant}
      data-size={size}
    >
      {brand || description || navigation || columns?.length ? (
        <div className="ui-footer-main">
          {brand || description ? (
            <div className="ui-footer-identity">
              {brand ? <div className="ui-footer-brand">{brand}</div> : null}
              {description ? <div className="ui-footer-description">{description}</div> : null}
            </div>
          ) : null}
          {navigation ? (
            <nav className="ui-footer-navigation" aria-label={navigationLabel}>
              {navigation}
            </nav>
          ) : null}
          {columns?.length ? (
            <div className="ui-footer-columns">
              {columns.map((column) => (
                <nav
                  key={column.title}
                  className="ui-footer-column"
                  aria-label={column.label ?? column.title}
                >
                  <h3>{column.title}</h3>
                  {column.content}
                </nav>
              ))}
            </div>
          ) : null}
        </div>
      ) : null}
      {children ? <div className="ui-footer-content">{children}</div> : null}
      {copyright || meta ? (
        <div className="ui-footer-bottom">
          {copyright ? <div className="ui-footer-copyright">{copyright}</div> : null}
          {meta ? <div className="ui-footer-meta">{meta}</div> : null}
        </div>
      ) : null}
    </footer>
  )
})
